function uid(prefix){return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`}
function loadProjects(){try{const data=JSON.parse(localStorage.getItem(STORAGE_KEY)||localStorage.getItem(LEGACY_STORAGE_KEY));if(!Array.isArray(data)||!data.length)return structuredClone(seedProjects);const migrated=data.map(project=>project.id==="projekt-filmarchiv"&&project.films?.length===LEGACY_DEMO_FILM_IDS.size&&project.films.every(film=>LEGACY_DEMO_FILM_IDS.has(film.id))?{...project,description:"Persönliches Filmarchiv.",films:[]}:project);localStorage.setItem(STORAGE_KEY,JSON.stringify(migrated));return migrated}catch{return structuredClone(seedProjects)}}
