function catalogFilms(){let films=catalogProjectId==="all"?projects.flatMap(project=>project.films):projects.find(project=>project.id===catalogProjectId)?.films||[];if(catalogPlaylistId!=="all"){const playlist=playlists.find(item=>sameId(item.id,catalogPlaylistId)),ids=new Set((playlist?.filmIds||[]).map(String));films=films.filter(film=>ids.has(String(film.id)))}return films}
function filmLanguages(film){const found=new Map();filmCopies(film).forEach(copy=>String(copy.languages||"").split(/[,;/|]+/).map(language=>language.trim()).filter(Boolean).forEach(language=>{const key=language.toLocaleLowerCase("de");if(!found.has(key))found.set(key,language)}));return [...found.entries()].map(([key,label])=>({key,label}))}
function archiveLanguageOptions(){const counts=new Map(),labels=new Map();projects.flatMap(project=>project.films).forEach(film=>filmLanguages(film).forEach(({key,label})=>{counts.set(key,(counts.get(key)||0)+1);if(!labels.has(key))labels.set(key,label)}));return [...counts].map(([key,count])=>({key,label:labels.get(key),count})).sort((a,b)=>b.count-a.count||a.label.localeCompare(b.label,"de",{sensitivity:"base"}))}
function renderCatalogLanguageFilters(){const options=archiveLanguageOptions(),available=new Set(options.map(option=>option.key));selectedCatalogLanguages=new Set([...selectedCatalogLanguages].filter(language=>available.has(language)));$("catalogLanguagesEmpty").hidden=options.length>0;$("catalogLanguageFilters").hidden=!options.length;$("catalogLanguageFilters").innerHTML=options.map(option=>`<label><input type="checkbox" value="${esc(option.key)}" ${selectedCatalogLanguages.has(option.key)?"checked":""}><span>${esc(option.label)}</span><small>${option.count}</small></label>`).join("")}
function filmCollectionNumber(film){const relevant=catalogPlaylistId==="all"?playlists:playlists.filter(playlist=>sameId(playlist.id,catalogPlaylistId));for(const playlist of relevant){const number=playlistNumber(playlist,film.id);if(number)return number}return ""}
function filmMatchesQuery(film,query){const q=String(query||"").trim().toLowerCase();return !q||[film.title,film.originalTitle,film.director,film.cast,film.genre,film.countries,String(film.year),...filmCopies(film).flatMap(copy=>[copy.title||copy.label||"",copy.languages,copy.resolution,copy.quality])].join(" ").toLowerCase().includes(q)}
function filteredFilms(){const q=els.searchInput.value;const films=catalogFilms().filter(f=>(activeGenre==="Alle"||(f.genre||"").split(",").map(x=>x.trim()).includes(activeGenre))&&(selectedCatalogLanguages.size===0||filmLanguages(f).some(language=>selectedCatalogLanguages.has(language.key)))&&filmMatchesQuery(f,q));const byTitle=(a,b)=>String(a.title||"").localeCompare(String(b.title||""),"de",{sensitivity:"base"}),byCollectionNumber=(a,b)=>{const aNumber=filmCollectionNumber(a),bNumber=filmCollectionNumber(b);if(!aNumber)return bNumber?1:byTitle(a,b);if(!bNumber)return -1;return aNumber.localeCompare(bNumber,"de",{numeric:true,sensitivity:"base"})||byTitle(a,b)},randomValue=film=>{const id=String(film.id);if(!catalogRandomOrder.has(id))catalogRandomOrder.set(id,Math.random());return catalogRandomOrder.get(id)};return films.sort((a,b)=>catalogSort==="random"?randomValue(a)-randomValue(b):catalogSort==="collection-number"?byCollectionNumber(a,b):catalogSort==="year-desc"?(Number(b.year)||0)-(Number(a.year)||0)||byTitle(a,b):catalogSort==="year-asc"?(Number(a.year)||9999)-(Number(b.year)||9999)||byTitle(a,b):catalogSort==="genre"?String(a.genre||"").localeCompare(String(b.genre||""),"de",{sensitivity:"base"})||byTitle(a,b):byTitle(a,b))}
