function render(){const p=activeProject();if(!p)return;els.projectSelect.innerHTML=`<option value="all" ${catalogProjectId==="all"?"selected":""}>Alle Projekte</option>`+projects.map(x=>`<option value="${x.id}" ${x.id===catalogProjectId?"selected":""}>${esc(x.name)}</option>`).join("");els.projectList.innerHTML=projects.map(x=>`<div class="project-row ${x.id===p.id?"is-active":""}"><button class="project-item" type="button" data-project-id="${x.id}"><span>${esc(x.name)}</span><small>${x.films.length}</small></button><div class="project-row-menu-wrap"><button class="project-row-menu-button" type="button" data-project-row-menu="${x.id}" aria-label="Menü für ${esc(x.name)} öffnen" aria-expanded="false">⋮</button><div class="project-row-menu" data-project-row-popup="${x.id}" hidden><button class="project-delete-button" type="button" data-delete-project="${x.id}">Löschen</button></div></div></div>`).join("");els.projectHeading.textContent=catalogProjectId==="all"?"Alle Projekte":projects.find(x=>x.id===catalogProjectId)?.name||"Alle Projekte";els.machineProjectTitle.textContent=p.name;els.projectSummary.textContent=`${p.films.length} ${p.films.length===1?"Film":"Filme"} · ${p.description||"Ohne Beschreibung"}`;renderPlaylists();renderFilters();renderCatalog();renderTable();renderHero()}
function renderPlaylists(){const active=playlists.find(item=>item.id===activePlaylistId);els.playlistList.innerHTML=playlists.map(item=>`<div class="project-row ${item.id===activePlaylistId?"is-active":""}"><button class="project-item" type="button" data-playlist-id="${item.id}"><span>${esc(item.name)}</span><small>${item.filmIds?.length||0}</small></button><div class="project-row-menu-wrap"><button class="project-row-menu-button" type="button" data-playlist-row-menu="${item.id}" aria-label="Menü für ${esc(item.name)} öffnen" aria-expanded="false">⋮</button><div class="project-row-menu" data-playlist-row-popup="${item.id}" hidden><button type="button" data-delete-playlist="${item.id}">Löschen</button></div></div></div>`).join("");els.playlistTitle.textContent=active?.name||"Playlisten";els.playlistSummary.textContent=active?`${active.filmIds?.length||0} ${active.filmIds?.length===1?"Film":"Filme"} · ${active.description||"Ohne Beschreibung"}`:"Noch keine Playlist angelegt.";$("playlistEmptyTitle").textContent=active?"Diese Playlist ist noch leer.":"Filme für einen Abend zusammenstellen";$("playlistEmptyText").textContent=active?"Die Filmzuordnung folgt direkt aus dem Filmarchiv.":"Lege links deine erste Playlist an."}
