let genresExpanded=false,genreFiltersVisible=true,genreOverflowFrame;
function updateGenreOverflow(){cancelAnimationFrame(genreOverflowFrame);genreOverflowFrame=requestAnimationFrame(()=>{if(!genreFiltersVisible){els.genreToggle.hidden=true;return}els.genreFilters.classList.remove("is-expanded");const overflowing=els.genreFilters.scrollHeight>els.genreFilters.clientHeight+1;if(genresExpanded&&overflowing)els.genreFilters.classList.add("is-expanded");els.genreToggle.hidden=!overflowing;els.genreToggle.setAttribute("aria-expanded",String(genresExpanded&&overflowing));els.genreToggle.innerHTML=genresExpanded&&overflowing?'Weniger Genres <span aria-hidden="true">⌃</span>':'Mehr Genres <span aria-hidden="true">⌄</span>'})}
