function alignCatalogControls(){cancelAnimationFrame(catalogAlignmentFrame);catalogAlignmentFrame=requestAnimationFrame(()=>{const cards=[...els.filmGrid.children];if(!cards.length){els.catalogHeading.style.removeProperty("--catalog-right-inset");return}const gridRect=els.filmGrid.getBoundingClientRect(),firstTop=cards[0].getBoundingClientRect().top;const firstRow=cards.filter(card=>Math.abs(card.getBoundingClientRect().top-firstTop)<2);const rowRight=Math.max(...firstRow.map(card=>card.getBoundingClientRect().right));els.catalogHeading.style.setProperty("--catalog-right-inset",`${Math.max(0,gridRect.right-rowRight)}px`)})}
function renderCatalogMenu(){if(catalogPlaylistId!=="all"&&!playlists.some(item=>sameId(item.id,catalogPlaylistId)))catalogPlaylistId="all";$("catalogPlaylistSelect").innerHTML='<option value="all">Alle Playlisten</option>'+playlists.map(item=>`<option value="${esc(item.id)}" ${sameId(item.id,catalogPlaylistId)?"selected":""}>${esc(item.name)}</option>`).join("");$("catalogSortSelect").value=catalogSort;$("catalogOriginalTitleToggle").checked=showCatalogOriginalTitles;renderCatalogLanguageFilters()}
