function startFilmDrag(event){const handle=event.target.closest("[data-drag-film-id]");if(!handle)return;draggedFilmReference={filmId:handle.dataset.dragFilmId,projectId:handle.dataset.dragProjectId};handle.classList.add("is-dragging");event.dataTransfer.effectAllowed="move";event.dataTransfer.setData("text/plain",handle.dataset.dragFilmId);if(event.dataTransfer.setDragImage)event.dataTransfer.setDragImage(handle,24,24)}
function dragFilmOverProject(event){const row=projectDropRow(event.target),targetId=row?.querySelector("[data-project-id]")?.dataset.projectId;if(!draggedFilmReference||!targetId||sameId(targetId,draggedFilmReference.projectId))return;event.preventDefault();event.dataTransfer.dropEffect="move";clearProjectDropTargets();row.classList.add("is-film-drop-target")}
function leaveFilmProject(event){const row=projectDropRow(event.target);if(row&&!row.contains(event.relatedTarget))row.classList.remove("is-film-drop-target")}
function dropFilmOnProject(event){const row=projectDropRow(event.target),targetId=row?.querySelector("[data-project-id]")?.dataset.projectId,reference=draggedFilmReference;event.preventDefault();clearFilmDropState();draggedFilmReference=null;if(!reference||!targetId||sameId(targetId,reference.projectId))return;const source=projects.find(project=>sameId(project.id,reference.projectId)),target=projects.find(project=>sameId(project.id,targetId)),filmIndex=source?.films.findIndex(film=>sameId(film.id,reference.filmId))??-1;if(!source||!target||filmIndex<0)return;const [film]=source.films.splice(filmIndex,1);target.films.unshift(film);save();render();toast(`„${film.title}“ nach „${target.name}“ verschoben`)}
