function renderFilmPlaylistChecklist(){$("filmPlaylistsEmpty").hidden=playlists.length>0;$("filmPlaylistChecklist").hidden=!playlists.length;$("filmPlaylistChecklist").innerHTML=playlists.map(playlist=>{const id=String(playlist.id),checked=editingPlaylistIds.has(id);return `<div class="film-playlist-option"><label class="playlist-check-main"><input data-playlist-check type="checkbox" value="${esc(id)}" ${checked?"checked":""}><span><strong>${esc(playlist.name)}</strong><small>${playlist.filmIds?.length||0} ${playlist.filmIds?.length===1?"Film":"Filme"}</small></span></label><label class="playlist-number-field"><span>Sammlungsnummer</span><input data-playlist-number maxlength="6" pattern="[A-Za-z0-9]{0,6}" inputmode="text" value="${esc(editingPlaylistNumbers.get(id)||"")}" placeholder="ABC123"></label></div>`}).join("");$("filmPlaylistChecklist").querySelectorAll("[data-playlist-check]").forEach(input=>input.addEventListener("change",updateFilmPlaylistCount));$("filmPlaylistChecklist").querySelectorAll("[data-playlist-number]").forEach(input=>input.addEventListener("input",()=>{input.value=input.value.replace(/[^A-Za-z0-9]/g,"").slice(0,6)}));updateFilmPlaylistCount()}
function readFilmPlaylistChecklist(){editingPlaylistIds=new Set();editingPlaylistNumbers=new Map();$("filmPlaylistChecklist").querySelectorAll(".film-playlist-option").forEach(row=>{const checkbox=row.querySelector("[data-playlist-check]"),number=row.querySelector("[data-playlist-number]").value.trim();if(checkbox.checked){editingPlaylistIds.add(String(checkbox.value));editingPlaylistNumbers.set(String(checkbox.value),number)}})}
function readCopyEditor(){editingCopies=[...$("filmCopiesList").querySelectorAll("[data-copy-id]")].map(row=>({id:row.dataset.copyId,title:row.querySelector('[data-copy-field="title"]').value.trim(),link:row.querySelector('[data-copy-field="link"]').value.trim(),languages:row.querySelector('[data-copy-field="languages"]').value.trim(),resolution:row.querySelector('[data-copy-field="resolution"]').value,quality:row.querySelector('[data-copy-field="quality"]').value,status:row.querySelector('[data-copy-field="status"]').value}))}
function renderCopyEditor(){$("filmCopyCount").textContent=editingCopies.length;$("filmCopiesEmpty").hidden=editingCopies.length>0;$("filmCopiesList").innerHTML=editingCopies.map((copy,index)=>`<section class="film-copy" data-copy-id="${esc(copy.id)}"><div class="film-copy-head"><strong>Fassung ${index+1}</strong><button type="button" data-remove-copy="${esc(copy.id)}" aria-label="Fassung ${index+1} entfernen">Entfernen</button></div><div class="copy-grid"><label>Quelle<input data-copy-field="title" maxlength="160" value="${esc(copy.title||copy.label||"")}" placeholder="z. B. Deutsche Kinofassung"></label><label>Sprache(n)<input data-copy-field="languages" maxlength="120" value="${esc(copy.languages||"")}" placeholder="Deutsch, Englisch"></label><label class="span-2">Link zum Film<input data-copy-field="link" type="url" value="${esc(copy.link||"")}" placeholder="https://… oder file:///…"></label><label>Auflösung<select data-copy-field="resolution"><option value="">Nicht angegeben</option>${["4K / UHD","1080p","720p","576p","480p","Andere"].map(value=>`<option ${copy.resolution===value?"selected":""}>${value}</option>`).join("")}</select></label><label>Qualität<select data-copy-field="quality"><option value="">Nicht bewertet</option>${["Hervorragend","Sehr gut","Gut","Akzeptabel","Schlecht"].map(value=>`<option ${copy.quality===value?"selected":""}>${value}</option>`).join("")}</select></label><label>Status<select data-copy-field="status"><option value="verfügbar" ${copy.status==="verfügbar"?"selected":""}>Verfügbar</option><option value="prüfen" ${copy.status==="prüfen"?"selected":""}>Link prüfen</option><option value="nicht verfügbar" ${copy.status==="nicht verfügbar"?"selected":""}>Nicht verfügbar</option></select></label></div></section>`).join("");$("filmCopiesList").querySelectorAll("[data-remove-copy]").forEach(button=>button.addEventListener("click",()=>{readCopyEditor();editingCopies=editingCopies.filter(copy=>!sameId(copy.id,button.dataset.removeCopy));renderCopyEditor()}))}
function addFilmCopy(){readCopyEditor();editingCopies.push({id:uid("copy"),title:`Fassung ${editingCopies.length+1}`,link:"",languages:"",resolution:"",quality:"",status:"verfügbar"});renderCopyEditor();setFilmTab("copies")}
function openFilmForm(id){const f=activeProject().films.find(x=>sameId(x.id,id)),filmId=f?.id||uid("film");$("filmDialogTitle").textContent=f?"Film bearbeiten":"Film anlegen";$("deleteFilmButton").hidden=!f;const fields={filmId,filmTmdbId:f?.tmdbId||"",filmTitle:f?.title||"",filmOriginalTitle:f?.originalTitle||"",filmYear:f?.year||"",filmRuntime:normalizeRuntime(f?.runtime),filmDirector:f?.director||"",filmCast:f?.cast||"",filmGenre:f?.genre||"",filmCountries:f?.countries||"",filmTrailer:f?.trailer||"",filmCover:f?.cover||"",filmRating:f?.rating||"",filmDescription:f?.description||""};Object.entries(fields).forEach(([fieldId,v])=>$(fieldId).value=v);editingCopies=filmCopies(f).map(copy=>({...copy,id:copy.id||uid("copy")}));editingPlaylistIds=new Set(playlists.filter(playlist=>(playlist.filmIds||[]).some(itemId=>sameId(itemId,filmId))).map(playlist=>String(playlist.id)));editingPlaylistNumbers=new Map(playlists.map(playlist=>[String(playlist.id),playlistNumber(playlist,filmId)]));renderCopyEditor();renderFilmPlaylistChecklist();setFilmTab("general");resetTmdbPanel(f);els.filmDialog.showModal()}
function saveFilm(){if(!$("filmTitle").value.trim())return;readCopyEditor();readFilmPlaylistChecklist();const copies=editingCopies.filter(copy=>copy.link||copy.title||copy.languages||copy.resolution||copy.quality);const primary=copies[0]||{};const data={id:$("filmId").value||uid("film"),tmdbId:$("filmTmdbId").value.trim(),title:$("filmTitle").value.trim(),originalTitle:$("filmOriginalTitle").value.trim(),year:Number($("filmYear").value)||"",runtime:normalizeRuntime($("filmRuntime").value),director:$("filmDirector").value.trim(),cast:$("filmCast").value.trim(),genre:$("filmGenre").value.trim(),countries:$("filmCountries").value.trim(),link:primary.link||"",copies,trailer:$("filmTrailer").value.trim(),cover:$("filmCover").value.trim(),status:primary.status||"nicht verfügbar",rating:$("filmRating").value.trim(),description:$("filmDescription").value.trim()};const p=activeProject(),i=p.films.findIndex(f=>sameId(f.id,data.id));if(i>=0)p.films[i]=data;else p.films.unshift(data);playlists.forEach(playlist=>{playlist.filmIds=(playlist.filmIds||[]).filter(itemId=>!sameId(itemId,data.id));playlist.filmAssignments=(playlist.filmAssignments||[]).filter(entry=>!sameId(entry.filmId,data.id));if(editingPlaylistIds.has(String(playlist.id))){playlist.filmIds.push(data.id);playlist.filmAssignments.push({filmId:data.id,collectionNumber:editingPlaylistNumbers.get(String(playlist.id))||""})}});save();render();toast(i>=0?"Film aktualisiert":"Film angelegt")}
function deleteFilm(){const id=$("filmId").value;if(!id||!confirm("Diesen Filmeintrag löschen?"))return;activeProject().films=activeProject().films.filter(f=>!sameId(f.id,id));playlists.forEach(playlist=>{playlist.filmIds=(playlist.filmIds||[]).filter(itemId=>!sameId(itemId,id));playlist.filmAssignments=(playlist.filmAssignments||[]).filter(entry=>!sameId(entry.filmId,id))});els.filmDialog.close();save();render();toast("Film gelöscht")}
function showDetail(id){const owner=projects.find(project=>project.films.some(film=>sameId(film.id,id)));if(!owner)return;const f=owner.films.find(film=>sameId(film.id,id)),copies=filmCopies(f);activeProjectId=owner.id;const copyActions=copies.map((copy,index)=>copy.link?`<a class="copy-action" href="${esc(copy.link)}" target="_blank" rel="noopener noreferrer"><span>▶ ${esc(copy.title||copy.label||`Fassung ${index+1}`)}</span><small>${esc([copy.languages,copy.resolution,copy.quality].filter(Boolean).join(" · ")||"Film öffnen")}</small></a>`:"").join("");$("detailContent").innerHTML=`<div class="detail-layout"><div class="detail-poster" style="${posterStyle(f)}">${cover(f)}<span class="poster-fallback"><strong>${esc(f.originalTitle||f.title)}</strong></span></div><div class="detail-body"><button class="dialog-close" style="float:right" type="button" data-close-detail aria-label="Schließen">×</button><p class="eyebrow">${esc(f.genre||"Film")}</p><h2>${esc(f.originalTitle||f.title)}</h2><div class="detail-meta">${esc([f.year,normalizeRuntime(f.runtime),f.rating,f.director].filter(Boolean).join(" · "))}</div>${f.countries?`<p class="detail-countries"><strong>Länder</strong> ${esc(f.countries)}</p>`:""}<p>${esc(f.description||"Keine Beschreibung hinterlegt.")}</p>${f.cast?`<p class="detail-cast"><strong>Mit</strong> ${esc(f.cast)}</p>`:""}${copyActions?`<div class="detail-copies"><strong>Meine Fassungen</strong>${copyActions}</div>`:""}<div class="detail-actions">${!copyActions?`<button disabled>Keine Fassung hinterlegt</button>`:""}${f.trailer?`<a class="secondary-action" href="${esc(f.trailer)}" target="_blank" rel="noopener noreferrer">Trailer ansehen</a>`:""}<button class="secondary-action" type="button" data-edit-from-detail="${esc(f.id)}">Bearbeiten</button></div></div></div>`;if(!els.detailDialog.open)els.detailDialog.showModal()}
function createProject(){const name=$("projectName").value.trim();if(!name)return;const p={id:uid("projekt"),name,description:$("projectDescription").value.trim(),createdAt:new Date().toISOString(),films:[]};projects.push(p);activeProjectId=p.id;save();render();toast("Projekt angelegt")}
function createPlaylist(){const name=$("playlistName").value.trim();if(!name)return;const playlist={id:uid("playlist"),name,description:$("playlistDescription").value.trim(),createdAt:new Date().toISOString(),filmIds:[]};playlists.push(playlist);activePlaylistId=playlist.id;save();render();setArchiveSection("playlists");toast("Playlist angelegt")}
function selectPlaylist(id){if(!playlists.some(item=>item.id===id))return;activePlaylistId=id;save();render();setArchiveSection("playlists")}
function deletePlaylist(id){const playlist=playlists.find(item=>item.id===id);if(!playlist||!confirm(`Playlist „${playlist.name}“ löschen?`))return;playlists=playlists.filter(item=>item.id!==id);if(activePlaylistId===id)activePlaylistId=playlists[0]?.id||"";save();render();setArchiveSection("playlists");toast("Playlist gelöscht")}
function exportProject(){const p=activeProject();const payload={format:"videothek-project",version:1,exportedAt:new Date().toISOString(),project:p};const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`${p.name.toLowerCase().replace(/[^a-z0-9äöüß]+/gi,"-")||"videothek-projekt"}.videothek.json`;a.click();URL.revokeObjectURL(a.href);toast("Projekt exportiert")}
async function importProject(file){try{const data=JSON.parse(await file.text());const p=["videothek-project","filmmap-project"].includes(data?.format)?data.project:data;if(!p||typeof p.name!=="string"||!Array.isArray(p.films))throw new Error();const imported={...p,id:uid("projekt"),name:`${p.name} (Import)`,films:p.films.map(f=>({...f,id:uid("film")}))};projects.push(imported);activeProjectId=imported.id;save();render();toast("Projekt importiert")}catch{toast("Diese Datei ist kein gültiges Videothek-Projekt")}}
async function importGoogleLibrary(file){try{const text=await file.text();const extension=file.name.split(".").pop().toLowerCase();const type=extension==="json"||file.type.includes("json")?"json":"csv";const result=VideothekImport.parseLibrary(text,type);if(!result.films.length)throw new Error("Keine Filmeinträge gefunden");const baseName=file.name.replace(/\.(csv|json)$/i,"").trim()||"Google-Bibliothek";const imported={id:uid("projekt"),name:`${baseName} · Google`,description:`Aus ${file.name} importierte Google-TV-/YouTube-Bibliothek.`,createdAt:new Date().toISOString(),source:{provider:"Google TV / YouTube",fileName:file.name,importedAt:new Date().toISOString(),format:type},films:result.films.map(f=>({...f,id:uid("film")}))};projects.push(imported);activeProjectId=imported.id;activeGenre="Alle";save();render();const duplicateNote=result.duplicates?` · ${result.duplicates} Dubletten übersprungen`:"";toast(`${result.films.length} Filme importiert${duplicateNote}`)}catch(error){toast(error instanceof SyntaxError?"Die JSON-Datei konnte nicht gelesen werden":"Keine gültige Google-Filmliste gefunden")}}
async function importAnyFile(file){if(file.name.toLowerCase().endsWith(".json")){try{const data=JSON.parse(await file.text());if(["videothek-project","filmmap-project"].includes(data?.format)||(data?.name&&Array.isArray(data?.films))){await importProject(file);return}}catch{toast("Die JSON-Datei konnte nicht gelesen werden");return}}await importGoogleLibrary(file)}
let pastedCandidates=[];
function openPasteImport(){$("pasteProjectName").value="Meine Google-Filme";$("pasteSource").value="";$("pasteResultSummary").textContent="";$("pastePreview").innerHTML="";$("pastePreviewFieldset").hidden=true;$("confirmPasteButton").disabled=true;pastedCandidates=[];$("pasteDialog").showModal();setTimeout(()=>$("pasteSource").focus(),0)}
function analyzePasted(){const result=VideothekImport.parsePastedLibrary($("pasteSource").value);pastedCandidates=result.films;$("pasteResultSummary").textContent=result.films.length?`${result.films.length} mögliche Titel erkannt`:"Keine Titel erkannt";$("pastePreviewFieldset").hidden=!result.films.length;$("confirmPasteButton").disabled=!result.films.length;$("pastePreview").innerHTML=result.films.map((film,index)=>`<label><input type="checkbox" data-paste-index="${index}" checked><span><strong>${esc(film.title)}</strong><small>${esc(film.link||"Kein direkter Link erkannt")}</small></span></label>`).join("")}
function importPasted(){const selected=[...document.querySelectorAll("[data-paste-index]:checked")].map(input=>pastedCandidates[Number(input.dataset.pasteIndex)]).filter(Boolean);if(!selected.length){toast("Bitte mindestens einen Titel auswählen");return}const name=$("pasteProjectName").value.trim()||"Meine Google-Filme";const project={id:uid("projekt"),name,description:"Aus dem kopierten Inhalt der Google-TV-/YouTube-Bibliothek importiert.",createdAt:new Date().toISOString(),source:{provider:"Google TV / YouTube",importedAt:new Date().toISOString(),format:"clipboard"},films:selected.map(f=>({...f,id:uid("film")}))};projects.push(project);activeProjectId=project.id;activeGenre="Alle";save();render();$("pasteDialog").close();toast(`${selected.length} Titel als Projekt importiert`)}
let tmdbSearchResults=[];
function resetTmdbPanel(film){tmdbSearchResults=[];$("tmdbResults").innerHTML="";$("tmdbResults").hidden=true;$("tmdbTokenInput").value=tmdbToken;$("tmdbTokenRow").hidden=Boolean(tmdbToken);$("tmdbStatus").textContent=film?.tmdbId?`Mit TMDB ${film.tmdbId} verknüpft.`:""}
function tmdbRuntime(minutes){const total=Math.max(0,Number(minutes)||0)*60;return `${Math.floor(total/3600)}:${String(Math.floor(total%3600/60)).padStart(2,"0")}:00`}
async function fetchTmdb(path,params={}){if(!tmdbToken)throw new Error("token-missing");const url=new URL(`${TMDB_API_URL}${path}`);Object.entries(params).forEach(([key,value])=>{if(value!==""&&value!==undefined&&value!==null)url.searchParams.set(key,String(value))});const response=await fetch(url,{headers:{Accept:"application/json",Authorization:`Bearer ${tmdbToken}`}});if(!response.ok)throw new Error(`tmdb-${response.status}`);return response.json()}
function renderTmdbResults(results){tmdbSearchResults=results;$("tmdbResults").hidden=!results.length;$("tmdbResults").innerHTML=results.map((film,index)=>{const year=String(film.release_date||"").slice(0,4)||"—";const poster=film.poster_path?`<img src="${TMDB_IMAGE_BASE_URL}/w92${esc(film.poster_path)}" alt="">`:`<span class="tmdb-result-placeholder" aria-hidden="true"></span>`;return `<button type="button" class="tmdb-result" data-tmdb-result="${index}">${poster}<span><strong>${esc(film.title)}</strong><small>${esc(year)}${film.original_title&&film.original_title!==film.title?` · ${esc(film.original_title)}`:""}</small><em>${esc(film.overview||"Keine Beschreibung verfügbar.")}</em></span><b>Daten übernehmen</b></button>`}).join("");$("tmdbResults").querySelectorAll("[data-tmdb-result]").forEach(button=>button.addEventListener("click",()=>applyTmdbResult(tmdbSearchResults[Number(button.dataset.tmdbResult)])))}
async function searchTmdb(){const query=$("filmTitle").value.trim();if(!tmdbToken){$("tmdbTokenRow").hidden=false;$("tmdbTokenInput").focus();$("tmdbStatus").textContent="Bitte zuerst den TMDB API Read Access Token hinterlegen.";return}if(!query){$("tmdbStatus").textContent="Bitte zuerst einen Filmtitel eingeben.";$("filmTitle").focus();return}$("tmdbSearchButton").disabled=true;$("tmdbStatus").textContent="TMDB wird durchsucht …";$("tmdbResults").hidden=true;try{const payload=await fetchTmdb("/search/movie",{query,language:"de-DE",include_adult:"false",page:1});const results=(payload.results||[]).slice(0,8);renderTmdbResults(results);$("tmdbStatus").textContent=results.length?`${results.length} Treffer gefunden. Bitte den passenden Film auswählen.`:"Kein passender Film gefunden."}catch(error){$("tmdbStatus").textContent=error.message==="tmdb-401"?"Der TMDB-Token wurde nicht akzeptiert.":"TMDB konnte gerade nicht erreicht werden.";if(error.message==="tmdb-401")$("tmdbTokenRow").hidden=false}finally{$("tmdbSearchButton").disabled=false}}
function getGermanRating(details){const releases=(details.release_dates?.results||[]).find(item=>item.iso_3166_1==="DE")?.release_dates||[];const certification=releases.map(item=>String(item.certification||"").trim()).find(Boolean);return certification?`FSK ${certification.replace(/^FSK\s*/i,"")}`:""}
function getYoutubeTrailer(details){const videos=details.videos?.results||[];const trailer=videos.find(video=>video.site==="YouTube"&&video.type==="Trailer"&&video.official&&video.iso_639_1==="de")||videos.find(video=>video.site==="YouTube"&&video.type==="Trailer"&&video.official)||videos.find(video=>video.site==="YouTube"&&video.type==="Trailer");return trailer?.key?`https://www.youtube.com/watch?v=${encodeURIComponent(trailer.key)}`:""}
async function applyTmdbResult(result){if(!result?.id)return;$("tmdbStatus").textContent="Filminformationen werden geladen …";$("tmdbResults").querySelectorAll("button").forEach(button=>button.disabled=true);try{const details=await fetchTmdb(`/movie/${encodeURIComponent(result.id)}`,{language:"de-DE",append_to_response:"credits,videos,release_dates"});const director=(details.credits?.crew||[]).find(person=>person.job==="Director")?.name||"";const cast=(details.credits?.cast||[]).slice(0,16).map(person=>person.name).filter(Boolean).join(", ");const values={filmTmdbId:String(details.id),filmTitle:details.title||result.title||"",filmOriginalTitle:details.original_title||details.title||result.title||"",filmYear:String(details.release_date||"").slice(0,4),filmRuntime:tmdbRuntime(details.runtime),filmDirector:director,filmGenre:(details.genres||[]).map(genre=>genre.name).join(", "),filmCountries:(details.production_countries||[]).map(country=>country.name).filter(Boolean).join(", "),filmTrailer:getYoutubeTrailer(details),filmCover:details.poster_path?`${TMDB_IMAGE_BASE_URL}/w500${details.poster_path}`:"",filmRating:getGermanRating(details),filmDescription:details.overview||""};$("filmCast").value=cast;Object.entries(values).forEach(([id,value])=>{if(value)$(id).value=value});$("tmdbStatus").textContent=`Daten für „${details.title||result.title}“ übernommen. Deine Fassungen bleiben erhalten.`;$("tmdbResults").hidden=true}catch{$("tmdbStatus").textContent="Die Filmdetails konnten nicht geladen werden.";$("tmdbResults").querySelectorAll("button").forEach(button=>button.disabled=false)}}
function readTimemapTmdbToken(){return new Promise(resolve=>{if(!window.indexedDB){resolve("");return}const request=indexedDB.open("timemap-local-db",1);request.onerror=()=>resolve("");request.onupgradeneeded=()=>{request.transaction.abort();resolve("")};request.onsuccess=()=>{const db=request.result;if(!db.objectStoreNames.contains("appState")){db.close();resolve("");return}const transaction=db.transaction("appState","readonly");const getRequest=transaction.objectStore("appState").get("primary");getRequest.onerror=()=>{db.close();resolve("")};getRequest.onsuccess=()=>{const token=String(getRequest.result?.state?.tmdbApiToken||"").trim();db.close();resolve(token)}}})}
async function initializeTmdbToken(){if(tmdbToken)return;const timemapToken=await readTimemapTmdbToken();if(!timemapToken)return;tmdbToken=timemapToken;localStorage.setItem(TMDB_TOKEN_KEY,tmdbToken)}
let toastTimer;function toast(msg){els.toast.textContent=msg;els.toast.classList.add("is-visible");clearTimeout(toastTimer);toastTimer=setTimeout(()=>els.toast.classList.remove("is-visible"),2600)}
function closeProjectMenu(){$("projectMenu").hidden=true;$("projectMenuButton").setAttribute("aria-expanded","false")}
document.addEventListener("click",e=>{const t=e.target.closest("button");if(!e.target.closest(".project-menu-wrap"))closeProjectMenu();if(!e.target.closest(".project-row-menu-wrap"))closeProjectRowMenus();if(!t)return;if(t.dataset.view)setView(t.dataset.view);if(t.hasAttribute("data-open-machine"))setView("machine");if(t.dataset.archiveSection)setArchiveSection(t.dataset.archiveSection);if(t.dataset.projectId)selectProject(t.dataset.projectId);if(t.dataset.playlistId)selectPlaylist(t.dataset.playlistId);if(t.dataset.projectRowMenu)toggleProjectRowMenu(t.dataset.projectRowMenu);if(t.dataset.playlistRowMenu)togglePlaylistRowMenu(t.dataset.playlistRowMenu);if(t.dataset.deleteProject)deleteProject(t.dataset.deleteProject);if(t.dataset.deletePlaylist)deletePlaylist(t.dataset.deletePlaylist);if(t.dataset.genre){activeGenre=t.dataset.genre;render()}if(t.dataset.editFilm)openFilmForm(t.dataset.editFilm);if(t.hasAttribute("data-close-detail"))els.detailDialog.close();if(t.dataset.editFromDetail){els.detailDialog.close();setView("machine");setArchiveSection("projects");openFilmForm(t.dataset.editFromDetail)}});
els.projectSelect.addEventListener("change",e=>selectProject(e.target.value));els.searchInput.addEventListener("input",()=>{if(currentView!=="cinema")setView("cinema");else{renderCatalog();renderHero()}});$("addFilmButton").addEventListener("click",()=>openFilmForm());$("filmForm").addEventListener("submit",e=>{if(e.submitter?.value==="default")saveFilm()});$("deleteFilmButton").addEventListener("click",deleteFilm);$("addProjectButton").addEventListener("click",()=>{$("projectName").value="";$("projectDescription").value="";els.projectDialog.showModal()});$("projectForm").addEventListener("submit",e=>{if(e.submitter?.value==="default")createProject()});$("addPlaylistButton").addEventListener("click",()=>{$("playlistName").value="";$("playlistDescription").value="";els.playlistDialog.showModal()});$("playlistForm").addEventListener("submit",e=>{if(e.submitter?.value==="default")createPlaylist()});$("projectMenuButton").addEventListener("click",()=>{const willOpen=$("projectMenu").hidden;$ ("projectMenu").hidden=!willOpen;$("projectMenuButton").setAttribute("aria-expanded",String(willOpen))});$("exportButton").addEventListener("click",()=>{closeProjectMenu();exportProject()});$("importButton").addEventListener("click",()=>{closeProjectMenu();$("importInput").click()});$("importInput").addEventListener("change",e=>{if(e.target.files[0])importAnyFile(e.target.files[0]);e.target.value=""});$("pasteImportButton").addEventListener("click",()=>{closeProjectMenu();openPasteImport()});$("analyzePasteButton").addEventListener("click",analyzePasted);$("confirmPasteButton").addEventListener("click",importPasted);document.addEventListener("keydown",e=>{if(e.key==="Escape"){closeProjectMenu();closeProjectRowMenus()}});window.addEventListener("resize",alignCatalogControls);
$("catalogMenuButton").addEventListener("click",()=>setCatalogDrawer(!$("catalogDrawer").classList.contains("is-open")));
