$("tmdbTokenSaveButton").addEventListener("click",()=>{const token=$("tmdbTokenInput").value.trim();if(!token){$("tmdbStatus").textContent="Bitte einen TMDB API Read Access Token eingeben.";return}tmdbToken=token;localStorage.setItem(TMDB_TOKEN_KEY,tmdbToken);$("tmdbTokenRow").hidden=true;$("tmdbStatus").textContent="Token lokal gespeichert. Die Suche kann jetzt beginnen.";searchTmdb()});
document.querySelectorAll("[data-film-tab]").forEach(button=>button.addEventListener("click",()=>setFilmTab(button.dataset.filmTab)));
$("addFilmCopyButton").addEventListener("click",addFilmCopy);
els.filmTableBody.addEventListener("dragstart",startFilmDrag);
els.filmTableBody.addEventListener("dragend",()=>{draggedFilmReference=null;clearFilmDropState()});
els.projectList.addEventListener("dragover",dragFilmOverProject);
els.projectList.addEventListener("dragleave",leaveFilmProject);
els.projectList.addEventListener("drop",dropFilmOnProject);
window.addEventListener("resize",()=>{updateGenreOverflow();compactDirectorNames()});
// Die globale Suche wirkt in der jeweils geöffneten Ansicht, ohne diese zu wechseln.
els.searchInput.addEventListener("input",event=>{if(currentView==="cinema"){renderCatalog();renderHero()}else renderTable();event.stopImmediatePropagation()},{capture:true});
function registerWebMCP(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const add=(tool)=>Promise.resolve(ctx.registerTool(tool)).catch(()=>{});add({name:"list_videothek_projects",title:"Videothek-Projekte auflisten",description:"Listet die vorhandenen Videothek-Projekte und ihre Filmzahlen auf.",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>projects.map(p=>({id:p.id,name:p.name,filmCount:p.films.length}))});add({name:"create_videothek_project",title:"Videothek-Projekt anlegen",description:"Legt ein neues leeres Videothek-Projekt an und macht es zum aktiven Projekt.",inputSchema:{type:"object",properties:{name:{type:"string",minLength:1},description:{type:"string"}},required:["name"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:({name,description=""})=>{if(typeof name!=="string"||!name.trim())throw new Error("Ein Projektname ist erforderlich.");const p={id:uid("projekt"),name:name.trim(),description:String(description),createdAt:new Date().toISOString(),films:[]};projects.push(p);activeProjectId=p.id;save();render();return{id:p.id,name:p.name}}});add({name:"add_film_reference",title:"Filmverweis hinzufügen",description:"Fügt dem aktiven Projekt einen Film mit Metadaten und externem Speicherlink hinzu. Es wird keine Filmdatei gespeichert.",inputSchema:{type:"object",properties:{title:{type:"string",minLength:1},link:{type:"string"},year:{type:"integer"},genre:{type:"string"},description:{type:"string"}},required:["title","link"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:(input)=>{if(typeof input.title!=="string"||!input.title.trim()||typeof input.link!=="string")throw new Error("Titel und Link sind erforderlich.");const f={id:uid("film"),title:input.title.trim(),link:input.link.trim(),year:input.year||"",genre:input.genre||"",description:input.description||"",runtime:"",director:"",cover:"",trailer:"",status:"verfügbar",rating:""};activeProject().films.unshift(f);save();render();return{id:f.id,projectId:activeProjectId}}})}
initializeTmdbToken();registerWebMCP();render();setArchiveSection(activeArchiveSection);

